/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/
static void sense_key_in( Boolean instant_level );
/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

//--------------------------------------------------------------------------//

void sense_rs_can_key_in_init( void )
{
    
}

//--------------------------------------------------------------------------//

Boolean sense_rs_key_in_can( Boolean instant_level )
{		
	sense_key_in( instant_level );                
	
    return get_key_in_status();
}

//--------------------------------------------------------------------------//

void sense_key_in( Boolean instant_level )
{		
	Boolean old_status = get_key_in_status();	

	set_key_in_data_status( instant_level ); 

	if( old_status != get_key_in_status() )
	{
	    ATOMIC( key.bit.in = get_key_in_status() );
							
		cmd_q_insert( get_key_in_status() ? INPUT_KEY_IN_STATUS_ON :  INPUT_KEY_IN_STATUS_OFF , SENSE_RS_CAN_TIMEOUT_CMD_Q);

		TRACE_SENSE_RS_CAN("\n\r[KEY %s]\n\r" , get_key_in_status() ? "IN":"OUT" );					
	}
}

//--------------------------------------------------------------------------//

